import { drizzle } from 'drizzle-orm/node-postgres';
import pg, { Pool } from 'pg';
import * as schema from './schema';

// Force TIMESTAMP WITHOUT TZ (oid 1114) to always be read as UTC regardless of
// the Node.js process timezone. Without this, pg uses the process TZ to interpret
// the raw value, so a dev machine running BST reads the same stored instant as
// 1 hour earlier than a UTC Docker container — causing systematic display drift.
pg.types.setTypeParser(1114, (val: string) => new Date(val + 'Z'));

// Re-export schema types and table objects — safe to import anywhere
export * from './schema';

// Export inferred types for all tables
export type User = typeof schema.users.$inferSelect;
export type NewUser = typeof schema.users.$inferInsert;

export type Session = typeof schema.sessions.$inferSelect;
export type NewSession = typeof schema.sessions.$inferInsert;

export type Flight = typeof schema.flights.$inferSelect;
export type NewFlight = typeof schema.flights.$inferInsert;

export type FlightTime = typeof schema.flightTimes.$inferSelect;
export type NewFlightTime = typeof schema.flightTimes.$inferInsert;

export type FlightNote = typeof schema.flightNotes.$inferSelect;
export type NewFlightNote = typeof schema.flightNotes.$inferInsert;

export type FlightStatusHistory = typeof schema.flightStatusHistory.$inferSelect;
export type NewFlightStatusHistory = typeof schema.flightStatusHistory.$inferInsert;

export type WeatherDatum = typeof schema.weatherData.$inferSelect;
export type NewWeatherDatum = typeof schema.weatherData.$inferInsert;

export type AirportDaylight = typeof schema.airportDaylight.$inferSelect;
export type NewAirportDaylight = typeof schema.airportDaylight.$inferInsert;

export type Airport = typeof schema.airports.$inferSelect;
export type NewAirport = typeof schema.airports.$inferInsert;

export type ScraperLog = typeof schema.scraperLogs.$inferSelect;
export type NewScraperLog = typeof schema.scraperLogs.$inferInsert;

export type AircraftPosition = typeof schema.aircraftPositions.$inferSelect;
export type NewAircraftPosition = typeof schema.aircraftPositions.$inferInsert;

export type PushSubscription = typeof schema.pushSubscriptions.$inferSelect;
export type NewPushSubscription = typeof schema.pushSubscriptions.$inferInsert;

export type HistoricalWeather = typeof schema.historicalWeather.$inferSelect;
export type NewHistoricalWeather = typeof schema.historicalWeather.$inferInsert;

export type NotificationWatermark = typeof schema.notificationWatermark.$inferSelect;
export type NewNotificationWatermark = typeof schema.notificationWatermark.$inferInsert;
export { tryAcquireServiceLock } from './singleton';
export {
  clearAllTimers,
  countFlightsForDate,
  getActiveFlightsToday,
  getEstimatedTimesBatch,
  msSinceLastScrape,
  logSchedulerEvent,
  computeNextInterval,
  shouldSleep,
  computeWakeTime,
  type TimerState,
} from './scheduler';
export { canUpgradeStatus, isTerminalStatus } from './statusPriority';
export { ROUTE_FLIGHT_MINUTES, LOCATION_TO_IATA, routeFlightMinutes, locationToIata } from './constants';
export { GY_TZ, localToUtc, guernseyTodayStr, guernseyTomorrowStr, guernseyHour, nextGuernseyTime, checkTimezoneOffset } from './time';
export type { TimezoneCheckResult } from './time';

export type DbClient = ReturnType<typeof drizzle<typeof schema>>;

let _db: DbClient | null = null;

export function getDb(): DbClient {
  if (_db) return _db;
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL is not set');
  // Keep pool small per-service so 6 services don't exhaust PostgreSQL's
  // default max_connections (typically 100). Each service gets up to 5
  // connections; peak total = 30, leaving headroom for admin tools.
  const pool = new Pool({
    connectionString: url,
    max: 5,
    idleTimeoutMillis: 30_000,
    connectionTimeoutMillis: 5_000,
  });
  // Enforce UTC session timezone on every connection so that TIMESTAMP WITHOUT TZ
  // values written by pg are stored as UTC wall-clock, consistent with TZ=UTC containers.
  pool.on('connect', (client) => { client.query("SET TIME ZONE 'UTC'").catch(() => {}); });
  _db = drizzle(pool, { schema });
  return _db;
}

// Proxy-based `db` export — lazily initialises the pool on first use.
// Only import this from server-side code (*.server.ts / Node scrapers).
export const db: DbClient = new Proxy({} as DbClient, {
  get(_t, prop) {
    return (getDb() as unknown as Record<string | symbol, unknown>)[prop];
  },
  apply(_t, _this, args) {
    return (getDb() as unknown as (...a: unknown[]) => unknown)(...args);
  },
});

import * as cheerio from 'cheerio';
import { db, flights, flightStatusHistory, flightTimes, scraperLogs, canUpgradeStatus, routeFlightMinutes, locationToIata, localToUtc, guernseyTodayStr } from '@airways/database';
import { eq, and, isNull, sql, count, or, isNotNull } from 'drizzle-orm';

interface StatusUpdate {
  flightCode: string;
  flightDate: string; // YYYY-MM-DD
  statusTimestamp: Date;
  statusMessage: string;
}

interface ScrapedFlight {
  location: string;
  codes: string[]; // may be multiple for codeshare flights e.g. "GR670, LM670"
  scheduledTime: Date;
  flightDate: string; // YYYY-MM-DD
  type: 'arrivals' | 'departures';
  statusUpdates: StatusUpdate[];
}







const BASE_URL = process.env.GUERNSEY_AIRPORT_URL || 'https://www.airport.gg';
const API_URL = process.env.GUERNSEY_API_URL || 'https://www.airport.gg/arr-dep/json';
function getApiKey(): string {
  const key = process.env.GUERNSEY_API_KEY;
  if (!key) throw new Error('GUERNSEY_API_KEY environment variable is required');
  return key;
}

interface ApiFlightEntry {
  flight_time: string;
  flight_comment: string;
  flight_date: string;
  last_updated: string;
  flight_numbers: string[];
  flight_locations: string[];
  airlines: string[];
}

interface ApiResponse {
  arrivals: ApiFlightEntry[];
  departures: ApiFlightEntry[];
}

async function fetchApiData(): Promise<ApiResponse> {
  const url = `${API_URL}?key=${getApiKey()}`;
  console.log(`[Guernsey] Fetching API data → ${API_URL}`);
  const response = await fetch(url, {
    headers: {
      'Accept': 'application/json',
    },
    signal: AbortSignal.timeout(30_000),
  });
  if (!response.ok) {
    throw new Error(`HTTP ${response.status} from Guernsey API`);
  }
  return response.json() as Promise<ApiResponse>;
}

function mapApiEntriesToScrapedFlights(
  entries: ApiFlightEntry[],
  type: 'arrivals' | 'departures',
  filterDate?: string,
): ScrapedFlight[] {
  const results: ScrapedFlight[] = [];
  for (const entry of entries) {
    if (filterDate && entry.flight_date !== filterDate) continue;
    if (!entry.flight_numbers || entry.flight_numbers.length === 0) continue;

    const timeParts = entry.flight_time.match(/^(\d{1,2}):(\d{2})$/);
    if (!timeParts) continue;
    const hh = parseInt(timeParts[1]);
    const mm = parseInt(timeParts[2]);
    const scheduledTime = localToUtc(entry.flight_date, hh, mm);

    const location = entry.flight_locations.join(', ');
    const codes = entry.flight_numbers;
    const statusUpdates: StatusUpdate[] = [];

    if (entry.flight_comment) {
      const lastUpdated = parseInt(entry.last_updated, 10);
      const statusTimestamp = isNaN(lastUpdated) ? new Date() : new Date(lastUpdated * 1000);
      for (const flightCode of codes) {
        statusUpdates.push({
          flightCode,
          flightDate: entry.flight_date,
          statusTimestamp,
          statusMessage: entry.flight_comment,
        });
      }
    }

    results.push({
      location,
      codes,
      scheduledTime,
      flightDate: entry.flight_date,
      type,
      statusUpdates,
    });
  }
  return results;
}
function airlineCode(flightCode: string): string {
  const match = flightCode.match(/^([A-Z]{2})/);
  const code = match ? match[1] : 'XX';
  if (code === 'SI' || code === 'AT') return 'GR';
  return code;
}

async function fetchDayHtml(date: Date): Promise<string> {
  // airport.gg uses DDMMYYYY in the URL path under /arrivals-departures/history/
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const formattedDate = `${day}${month}${year}`;

  const url = `${BASE_URL}/arrivals-departures/history/${formattedDate}`;
  const dateStr = `${year}-${month}-${day}`;

  console.log(`[Guernsey] Fetching ${dateStr} → ${url}`);

  const response = await fetch(url, {
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
      'Accept-Language': 'en-GB,en;q=0.5',
    },
    signal: AbortSignal.timeout(30_000),
  });

  if (!response.ok) {
    throw new Error(`HTTP ${response.status} for ${url}`);
  }

  return response.text();
}

function parseFlightHtml(html: string, date: Date, type: 'arrivals' | 'departures'): ScrapedFlight[] {
  const $ = cheerio.load(html);
  const tableId = type === 'arrivals' ? '#table-arrivals' : '#table-departures';

  const results: ScrapedFlight[] = [];
  const defaultFlightDate = guernseyTodayStr(date);

  $(`${tableId} tbody.list tr[data-search="true"]`).each((_, row) => {
    try {
      const $row = $(row);

      const timeStr = $row.find('td.time').text().trim();
      const [hh, mm] = timeStr.split(':').map(Number);

      if (isNaN(hh) || isNaN(mm)) return;

      // If the row has an explicit date cell (airport.gg shows tomorrow's flights on today's
      // page with a visible date), use that date; otherwise fall back to the page's date.
      let flightDate = defaultFlightDate;
      let rowDate = date;
      const dateCellText = $row.find('td.date').text().trim();
      if (dateCellText) {
        const dateMatch = dateCellText.match(/(\d{2})\/(\d{2})\/(\d{4})/);
        if (dateMatch) {
          const [, d, mo, y] = dateMatch;
          flightDate = `${y}-${mo}-${d}`;
          rowDate = new Date(`${flightDate}T00:00:00Z`);
        }
      }

      const scheduledTime = localToUtc(flightDate, hh, mm);

      const location = $row.find('td.airport').text().trim();

      // Codeshare rows show multiple codes separated by commas e.g. "GR670, LM670"
      // Split and trim each, keep only non-empty codes within varchar(20) limit
      const codes = $row.find('td.flight').text().trim()
        .split(',')
        .map(c => c.trim())
        .filter(c => c.length > 0 && c.length <= 20);

      if (codes.length === 0) return;

      const statusUpdates: StatusUpdate[] = [];

      // Each status update has a separate span.datetime and span.comment
      // e.g. <span class="datetime">23/02/2026 09:16:</span> <span class="comment">Delayed To 10:40</span>
      $row.find('td.status div.status-change').each((_, div) => {
        const datetimeRaw = $(div).find('span.datetime').text().trim();
        const comment = $(div).find('span.comment').text().trim();

        if (!comment) return;

        // Parse "DD/MM/YYYY HH:MM:" from the dedicated datetime span
        const tsMatch = datetimeRaw.match(/(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2})/);
        if (tsMatch) {
          const [, d, mo, y, h, mi] = tsMatch;
          const dateStr = `${y}-${String(mo).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
          const statusTimestamp = localToUtc(dateStr, parseInt(h), parseInt(mi));
          if (!isNaN(statusTimestamp.getTime())) {
            for (const flightCode of codes) {
              statusUpdates.push({ flightCode, flightDate, statusTimestamp, statusMessage: comment });
            }
          }
          return;
        }

        // Fallback: no parseable datetime — use time of scrape
        for (const flightCode of codes) {
          statusUpdates.push({
            flightCode,
            flightDate,
            statusTimestamp: new Date(),
            statusMessage: comment,
          });
        }
      });

      results.push({ location, codes, scheduledTime, flightDate, type, statusUpdates });
    } catch (err) {
      console.error('[Guernsey] Error parsing row:', err);
    }
  });
  return results;
}
