/**
 * Current hour (0–23) in Guernsey local time.
 */
export function guernseyHour(d: Date = new Date()): number {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: GY_TZ,
    hour: 'numeric',
    hourCycle: 'h23',
  }).formatToParts(d);
  return parseInt(parts.find(p => p.type === 'hour')?.value ?? '0', 10);
}

