    timeZone: GY_TZ,
    hour: 'numeric',
    hourCycle: 'h23',
  }).formatToParts(noon);
  const noonHour = parseInt(parts.find(p => p.type === 'hour')?.value ?? '12', 10);
  const currentOffset = noonHour - 12;
  const isBstNow = currentOffset === 1;

