```typescript
function parseHHMM(text: string): { hh: number; mm: number } | null {
  const colonMatch = text.match(/(\d{1,2}):(\d{2})/);
  if (colonMatch) return { hh: parseInt(colonMatch[1]), mm: parseInt(colonMatch[2]) };
  const noColonMatch = text.match(/(?<!\d)(\d{2})(\d{2})(?!\d)/);
  if (noColonMatch) {
    const hh = parseInt(noColonMatch[1]);
    const mm = parseInt(noColonMatch[2]);
    if (hh >= 0 && hh <= 23 && mm >= 0 && mm <= 59) return { hh, mm };
  }
  return null;
}
```

For the colon-separated case, there's no bounds checking: `99:99` would return `{hh: 99, mm: 99}`. This flows into `localToUtc()`:

```typescript
export function localToUtc(dateStr: string, hh: number, mm: number): Date {
  const [y, m, d] = dateStr.split('-').map(Number);
  const offset = getUtcOffset(dateStr);
  return new Date(Date.UTC(y, m - 1, d, hh - offset, mm, 0));
}
```

